#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
	int l, r, d, u;
	cin >> l >> r >> d >> u;
	ll ans = 0;

	// |x| > |y|
	for (int x = l; x <= r; x++) {
		if (x % 2 == 0) {
			int D = max(d, -abs(x) + 1);
			int U = min(u, abs(x) - 1);
			int C = U - D + 1;
			ans += max(C, 0);
		}
	}

	// |x| <= |y|
	for (int y = d; y <= u; y++) {
		if (y % 2 == 0) {
			int L = max(l, -abs(y));
			int R = min(r, abs(y));
			int C = R - L + 1;
			ans += max(C, 0);
		}
	}

	cout << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int l, r, u, d;
    cin >> l >> r >> u >> d;
    long long ans = 0;
    while(l <= r && u <= d) {
        int ma = max({abs(l), abs(r), abs(u), abs(d)});
        if(abs(l) == ma) {
            if(l % 2 == 0) {
                ans += d - u + 1;
            }
            l += 1;
        } else if(abs(r) == ma) {
            if(r % 2 == 0) {
                ans += d - u + 1;
            }
            r -= 1;
        } else if(abs(u) == ma) {
            if(u % 2 == 0) {
                ans += r - l + 1;
            }
            u += 1;
        } else {
            if(d % 2 == 0) {
                ans += r - l + 1;
            }
            d -= 1;
        }
    }
    cout << ans << endl;
    return 0;
}
